Rule.fixtext:
Run the following command to remove the selinux=0 and enforcing=0 parameters: grubby --update-kernel ALL --remove-args "selinux=0 enforcing=0" Run the following command to remove the selinux=0 and enforcing=0 parameters if they were created by the deprecated grub2-mkconfig command: # grep -Prsq -- '\h*([^#
]+\h+)?kernelopts=([^#
]+\h+)?(selinux|enforcing)=0 ' /boot/grub2 /boot/efi && grub2-mkconfig -o "$(grep -Prl -- '\h*([^#
]+\h+)?kernelopts=([^#
]+\h+)?(selinux|enforcing)=0 ' /boot/grub2 /boot/efi)"

check.check-content:
Run the following script to ensure chrony is configured with an authorized timeserver: #!/usr/bin/env bash { a_output=() a_output2=() a_config_files=("/etc/chrony.conf") l_include='(confdir|sourcedir)' l_parameter_name='(server|pool)' l_parameter_value='.+' while IFS= read -r l_conf_loc; do l_dir="" l_ext="" if [ -d "$l_conf_loc" ]; then l_dir="$l_conf_loc" l_ext="*" elif grep -Psq '/\*\.([^#/
]+)?\h*$' <<< "$l_conf_loc" || [ -f "$(readlink -f "$l_conf_loc")" ]; then l_dir="$(dirname "$l_conf_loc")" l_ext="$(basename "$l_conf_loc")" fi if [[ -n "$l_dir" && -n "$l_ext" ]]; then while IFS= read -r -d $'\0' l_file_name; do [ -f "$(readlink -f "$l_file_name")" ] && a_config_files+=("$(readlink -f "$l_file_name")") done < <(find -L "$l_dir" -type f -name "$l_ext" -print0 2>/dev/null) fi done < <(awk '$1~/^\s*'"$l_include"'$/{print $2}' "${a_config_files[*]}" 2>/dev/null) for l_file in "${a_config_files[@]}"; do l_parameter_line="$(grep -Psi '^\h*'"$l_parameter_name"'(\h+|\h*:\h*)'"$l_parameter_value"' ' "$l_file")" [ -n "$l_parameter_line" ] && a_output+=(" - Parameter: "$(tr -d '()' <<< ${l_parameter_name//|/ or })"" \ " Exists in the file: "$l_file" as:" "$l_parameter_line") done [ "${#a_output[@]}" -le "0" ] && a_output2+=(" - Parameter: "$(tr -d '()' <<< ${l_parameter_name//|/ or })"" \ " Does not exist in the chrony configuration") if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" "" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " - Reason(s) for audit failure:" "${a_output2[@]}" fi }

Rule.fixtext:
- IF not using FirewallD - Run the following command to create the base chains:
# nft create chain inet <table name> <base chain name> { type filter hook
<(input|forward|output)> priority 0 \; }
Example:
# nft create chain inet filter input { type filter hook input priority 0 \; }
# nft create chain inet filter forward { type filter hook forward priority 0
\; }
# nft create chain inet filter output { type filter hook output priority 0 \;
}

If NFTables utility is in use on your system:
Run the following command for the base chains with the input, forward, and output hooks to implement a default DROP policy:
# nft chain <table family> <table name> <chain name> { policy drop \; }
Example:
# nft chain inet filter input { policy drop \; }
# nft chain inet filter forward { policy drop \; }

Run the following script to set mode, ownership, and group on the private SSH host key files: #!/usr/bin/env bash { a_output=(); a_output2=(); l_ssh_group_name="$(awk -F: '($1 ~ /^(ssh_keys|_?ssh)$/) {print $1}' /etc/group)" f_file_access_fix() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() [ "$l_file_group" = "$l_ssh_group_name" ] && l_pmask="0137" || l_pmask="0177" l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" if [ $(( $l_file_mode & $l_pmask )) -gt 0 ]; then a_out2+=(" Mode: "$l_file_mode" should be mode: "$l_maxperm" or more restrictive" \ " updating to mode: \:$l_maxperm"") if [ "l_file_group" = "$l_ssh_group_name" ]; then chmod u-x,g-wx,o-rwx "$l_file" else chmod u-x,go-rwx "$l_file" fi fi if [ "$l_file_owner" != "root" ]; then a_out2+=(" Owned by: "$l_file_owner" should be owned by "root"" \ " Changing ownership to "root"") chown root "$l_file" fi if [[ ! "$l_file_group" =~ ($l_ssh_group_name|root) ]]; then [ -n "$l_ssh_group_name" ] && l_new_group="$l_ssh_group_name" || l_new_group="root" a_out2+=(" Owned by group "$l_file_group" should be group owned by: "$l_ssh_group_name" or "root"" \ " Changing group ownership to "$l_new_group"") chgrp "$l_new_group" "$l_file" fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file"" \ "Correct: mode: "$l_file_mode", owner: "$l_file_owner", and group owner: "$l_file_group" configured") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- ' openssh\h+([^#
]+\h+)?private\h+key ' && f_file_access_fix fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le "0" ]; then printf '%s
' "" " - No access changes required" "" else printf '%s
' "" " - Remediation results:" "${a_output2[@]}" "" fi }

