\h]+\.conf ') if [ -d "$l_conf_loc" ]; then l_dir="$l_conf_loc" l_ext="*" elif grep -Psq '/\*\.([^#/
]+)?\h*$' <<< "$l_conf_loc" || [ -f "$(readlink -f "$l_conf_loc")" ]; then l_dir="$(dirname "$l_conf_loc")" l_ext="$(basename "$l_conf_loc")" fi while read -r -d $'\0' l_file_name; do [ -f "$(readlink -f "$l_file_name")" ] && a_config_files+=("$(readlink -f "$l_file_name")") done < <(find -L "$l_dir" -type f -name "$l_ext" -print0 2>/dev/null) for l_parameter in "${a_parameters[@]}"; do a_out=() a_out2=() for l_logfile in "${a_config_files[@]}"; do l_out=$(grep -Ps -- '^\h*([^#
]+;)?'"$l_parameter"' ([^#
]+)?\h+/var/log/.*$' "$l_logfile") if [ -n "$l_out" ]; then if grep -Psq -- '^\h*([^#
]+;)?'"$l_parameter"'\.\*(;[^#
]+)?\h+/var/log/secure ' <<< "$l_out"; then a_out+=(" - access method: "$l_parameter" exists in "$l_logfile" correctly configured" \ " as: "$l_out"") else a_out2+=(" - access method: "$l_parameter" exists in "$l_logfile" incorrectly configured" \ " as: "$l_out"") fi fi done [ "${#a_out[@]}" -gt 0 ] && a_output+=("${a_out[@]}") [ "${#a_out2[@]}" -gt 0 ] && a_output2+=("${a_out2[@]}") [[ "${#a_out[@]}" -le 0 && "${#a_out2[@]}" -le 0 ]] && \ a_output2+=(" - access method: "$l_parameter" does not exist in the rsyslog configuration") done if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" "" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " - Reason(s) for audit failure:" "${a_output2[@]}" [ "${#a_output[@]}" -gt 0 ] && printf '%s
' "" "- Correctly set:" "${a_output[@]}" "" fi }

Rule.fixtext:
Configure the system-wide shared library directories (/lib, /lib64, /usr/lib and /usr/lib64) to be protected from unauthorized access.
Run the following command, replacing "[DIRECTORY]" with any library directory not group-owned by root:
# chgrp root [DIRECTORY}

check.check-content:
Verify the system-wide shared library files contained in the following directories have mode "0755" or less permissive with the following command:
# find -L /lib /lib64 /usr/lib /usr/lib64 -perm /0022 -type f -exec ls -l {}
\;
If any system-wide shared library file is found to be group-writable or world-writable, this is a finding.

Verify the system-wide shared library files are owned by "root" with the following command:
# find -L /lib /lib64 /usr/lib /usr/lib64 ! -user root -exec ls -l {} \;
If any system wide shared library file is returned, this is a finding.

Verify the system-wide shared library files are group-owned by "root" with the following command:
# find -L /lib /lib64 /usr/lib /usr/lib64 ! -group root -exec ls -l {} \;
If any system wide shared library file is returned and is not group-owned by a required system account, this is a finding.

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_uid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate UID: \"$l_uid\" Users: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_uid /etc/passwd | xargs)\""
fi
done < <(cut -f3 -d":" /etc/passwd | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_gid; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate GID: \"$l_gid\" Groups: \"$(awk -F: '($3 == n) {
print $1 }' n=$l_gid /etc/group | xargs)\""
fi
done < <(cut -f3 -d":" /etc/group | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_user; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate User: \"$l_user\" Users: \"$(awk -F: '($1 == n) {
print $1 }' n=$l_user /etc/passwd | xargs)\""
fi
done < <(cut -f1 -d":" /etc/group | sort -n | uniq -c)
}

Run the following script and verify no results are returned:
#!/usr/bin/env bash
{
while read -r l_count l_group; do
if [ "$l_count" -gt 1 ]; then
echo -e "Duplicate Group: \"$l_group\" Groups: \"$(awk -F: '($1 ==
n) { print $1 }' n=$l_group /etc/group | xargs)\""
fi
done < <(cut -f1 -d":" /etc/group | sort -n | uniq -c)
}
